<style>
  * { box-sizing: border-box; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 13px;
    color: #000;
    margin: 20px 40px;
    max-width: 1650px;
  }
  .header-row {
    display: flex;
    align-items: baseline;
    gap: 10px;
  }
  .form-label { font-size: 13px; }
  .form-number { font-size: 34px; font-weight: 800; }
  .form-title { font-size: 26px; font-weight: 800; margin-left: 8px; }
  .subheader-row {
    display: flex;
