    background: #000;
    color: #fff;
    font-weight: bold;
    padding: 5px 8px;
    font-size: 14px;
  }
  .right-box-content {
    padding: 10px 12px;
  }

  .ein-row {
    display: flex;
    align-items: center;
    gap: 6px;
