  .ein-box.wide { width: 45px; }
  .field-label { font-weight: bold; }

  .field-row {
    display: flex;
    align-items: center;
    margin-top: 10px;
    gap: 8px;
  }
  .field-row .label {
    font-weight: bold;
    width: 200px;
